<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Roles | Kanozay ERP</title><style>body{font-family:Inter,Arial;background:#f3f6fb;color:#0d1f4c;margin:0}header{background:#0d1f4c;color:white;padding:18px 30px}main{max-width:1100px;margin:30px auto;padding:0 20px}.panel{background:white;border-radius:12px;padding:22px;margin-bottom:20px}input{padding:10px;border:1px solid #d6dfed;border-radius:7px}button{background:#1565e0;color:white;border:0;border-radius:7px;padding:10px 16px;cursor:pointer}.permissions{display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:9px;margin:18px 0}label{display:block;font-size:13px}a{color:#1565e0}.error{color:#ae2332}</style></head><body><header><strong>KANOZAY ERP</strong> &nbsp; / &nbsp; Roles & Permissions</header><main><p><a href="{{ route('dashboard') }}">Dashboard</a> &nbsp; <a href="{{ route('admin.users.index') }}">Users</a></p>@if(session('status'))<p>{{ session('status') }}</p>@endif @if($errors->any())<p class="error">{{ implode(' | ', $errors->all()) }}</p>@endif
@can('roles.create')<section class="panel"><h2>Create role</h2><form method="POST" action="{{ route('admin.roles.store') }}">@csrf<input name="name" placeholder="Role name" required><div class="permissions">@foreach($permissions as $permission)<label><input type="checkbox" name="permissions[]" value="{{ $permission->name }}"> {{ $permission->name }}</label>@endforeach</div><button>Create role</button></form></section>@endcan
@foreach($roles as $role)<section class="panel"><h3>{{ $role->name }} ({{ $role->permissions->count() }} permissions)</h3>@if($role->name !== 'Super Administrator')@can('roles.update')<form method="POST" action="{{ route('admin.roles.update',$role) }}">@csrf @method('PUT')<input name="name" value="{{ $role->name }}" required><div class="permissions">@foreach($permissions as $permission)<label><input type="checkbox" name="permissions[]" value="{{ $permission->name }}" @checked($role->hasPermissionTo($permission))> {{ $permission->name }}</label>@endforeach</div><button>Save permissions</button></form>@endcan @can('roles.delete')<form method="POST" action="{{ route('admin.roles.destroy',$role) }}" onsubmit="return confirm('Delete this role?')">@csrf @method('DELETE')<button>Delete role</button></form>@endcan @else<p>Protected system role. Full access is maintained by the system.</p>@endif</section>@endforeach</main></body></html>